# Export immutable student content and provenance; PDF crops use reviewed preview coordinates.
for r,items in DATA.items():
 assert len(items)==20,(r,len(items))
 out=BASE/'authoring'/f'round{r}';(out/'assets').mkdir(parents=True,exist_ok=True)
 pdf=fitz.open(BASE/'sources'/f'round{r}'/'source.pdf')
 metas=[]
 for i,item in enumerate(items,1):
  meta=item.pop('_meta');metas.append(meta)
  if i in CROPS[r]:
   page,x0,y0,x1,y1=CROPS[r][i];p=pdf[page-1];rect=fitz.Rect(x0/1.6,y0/1.6,x1/1.6,y1/1.6)
   p.get_pixmap(matrix=fitz.Matrix(3,3),clip=rect).save(str(out/'assets'/f'q{i:02}.png'));meta['sourcePage']=page
  for k in ['question','hint','explanation']:
   item[k]=re.sub(r'\\frac\s*([a-zA-Z0-9])\s*([a-zA-Z0-9])',r'\\frac{\1}{\2}',item[k])
 (out/'questions.json').write_text(json.dumps({'questions':items},ensure_ascii=False,indent=2)+'\n')
 (out/'manifest.json').write_text(json.dumps(dict(round=r,unitId='reg_1781420075936_chap_1781420235224_unit_'+UNITS[r],sourceTitle=f'중2 2학기 중간 실전모의고사 {r:02}',questions=metas),ensure_ascii=False,indent=2)+'\n')
 print('Authored',r,len(items),'images',sum(bool(m['imagePath']) for m in metas))
